    ProductVariantOption = apps.get_model('products', 'ProductVariantOption')
    database = schema_editor.connection.alias

    for product in Product.objects.using(database).all().iterator():
        if product.product_type == '1':
            product.product_type = 'simple'
        elif product.product_type == '2':
            product.product_type = 'grouped'
        elif product.product_type not in ('simple', 'grouped'):
            product.product_type = 'simple'

        if product.product_type == 'grouped':
            product.price = 0
            product.stock_quantity = 0
            product.save(update_fields=['product_type', 'price', 'stock_quantity'])
