        variant_count = variants.count()
        options = ProductVariantOption.objects.using(database).filter(product_id=product.pk)

        if variant_count == 0:
            base_sku = f'{product.sku}-DEFAULT'[:100]
            sku = base_sku
            suffix = 1
            while ProductVariant.objects.using(database).filter(sku=sku).exists():
                suffix_text = f'-{product.pk}-{suffix}'
                sku = f'{base_sku[:100 - len(suffix_text)]}{suffix_text}'
                suffix += 1
            ProductVariant.objects.using(database).create(
                product_id=product.pk,
                name='Default',
                sku=sku,
                price=product.price,
                stock_quantity=product.stock_quantity,
                is_default=True,
                created_by_id=product.created_by_id,
            )
        elif variant_count == 1 and not options.exists():
            variant = variants.first()
            variant.is_default = True
            variant.price = product.price
            variant.stock_quantity = product.stock_quantity
            variant.save(update_fields=['is_default', 'price', 'stock_quantity'])

        if variant_count == 0 or (variant_count == 1 and not options.exists()):
            ProductVariantOption.objects.using(database).create(
                product_id=product.pk,
                option_name='Default',
                option='Default',
                is_default=True,
                created_by_id=product.created_by_id,
            )


